package com.biocircular.compostaje.entity;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="observacion_etapa") public class ObservacionEtapa { @Id @GeneratedValue private UUID id; @ManyToOne @JoinColumn(name="lote_etapa_id") private LoteEtapa loteEtapa; @Column(name="responsable_usuario_externo_id") private UUID responsableId; @Column(name="fecha_hora") private OffsetDateTime fechaHora=OffsetDateTime.now(); @Column(name="nota_tecnica") private String nota; public UUID getId(){return id;} public LoteEtapa getLoteEtapa(){return loteEtapa;} public UUID getResponsableId(){return responsableId;} public OffsetDateTime getFechaHora(){return fechaHora;} public String getNota(){return nota;} public void crear(LoteEtapa le,UUID r,String n){loteEtapa=le;responsableId=r;nota=n;} }
